------------ import ------------
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
------------ import ------------
local worldBossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)
local CountDownTime = 2592000 --30 * 86400 30天的秒数
local CDTimerModule = CS.Engine.Modules.CDTimerModule
local CriWareUtils =  import('Game.Entry.CriWareUtilsFix')
local UINavigationBarRoot = CS.UINavigationBarRoot

---@class WorldBossNewBuffGetNode      
---@field BtnLogisticsText              	UnityEngine.RectTransform               
---@field FontStyleButton               	UnityEngine.RectTransform               
---@field TextNumber                    	UnityEngine.RectTransform               
---@field TextNO                        	UnityEngine.RectTransform               
