---@field Content                       	UnityEngine.RectTransform               
---@field BuffDesNode                   	UnityEngine.RectTransform               
---@field Imgbg                         	UnityEngine.RectTransform               
---@field LogisticsIconGroup            	UnityEngine.RectTransform               
---@field BtnInfo                       	UnityEngine.RectTransform               
---@field TxtTitle                      	UnityEngine.RectTransform               
local WorldBossNewBuffGetNode = Class('WorldBossNewBuffGetNode')

function WorldBossNewBuffGetNode:__init()
    self._data = nil        --当前buffid
    self._timeDown = nil
    self._timeClick = 0
end

function WorldBossNewBuffGetNode:__delete()
    self._data = nil        --当前buffid
    self._timeDown = nil
    self._timeClick = nil
end

function WorldBossNewBuffGetNode:Awake()
    SetButtonAction(self.BtnConfirm, Bind(self, self.OnBtnClose))
    SetButtonAction(self.BtnRefresh, Bind(self, self.OnBtnRefresh))
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        self._timeClick = self._timeClick - 1
    end, CountDownTime, false, true)

    SetButtonAction(self.controller.gameObject.transform:Find("CapturedBg"), function()
        CfUtils.PlayAnimator(self.Root, "WorldBossNewBuffRootIdle")
        self._timeClick = 0
    end)
end

function WorldBossNewBuffGetNode:Start()
    --self.Root:Capture()
end

function WorldBossNewBuffGetNode:Refresh(data)
    UINavigationBarRoot.Instance:SetActive(false)
    if not data then
        return
    end
    CfUtils.PlayAnimator(self.Root, "WorldBossNewBuffRoot")
    CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_world_boss_article)

    CfUtils.SetTopCommonActive(false)
    self._data = checkTable(data)        --当前bossVo
    self._timeClick = CfUtils.GetAnimatorTime(self.Root, "WorldBossNewBuffRoot")

    self:FillBuffInfo()
end

--绘制buff信息
function WorldBossNewBuffGetNode:FillBuffInfo()
    if self._data == nil then
        return 
    end

    self:FillBuffIcons(self._data)
    self:FillBuffDescs(self._data)

    local consumId = QuestConfMgr:GetInstance():GetWorldBossBuffRefreshConsumeId()
    local num = QuestConfMgr:GetInstance():GetWorldBossBuffRefreshConsumeNum()
    local freeNum = worldBossComponent:GetBuyBuffFreeNum()
    if freeNum > 0 then
        num = 0
    end
    CfUtils.FillCommonBtnConsumePopNode(self.CommonBtnConsumePop, consumId, num)
end

function WorldBossNewBuffGetNode:FillBuffIcons(data)
    if not data then
        return
    end

    for i = 1, #data do
        local go = self["Imgbg"..i]
        if go then
            local vo = QuestConfMgr:GetInstance():GetWorldBossBuffTypeVo(data[i].type)
            if vo then
                CfUtils.FillImage(go.transform:Find("ImgIcon"), vo.icon)
            end
        end
    end

    if #data < self.LogisticsIconGroup.childCount then
        for i = #data + 1, self.LogisticsIconGroup.childCount do
            local go = self["Imgbg"..i]
            if go then
                KTool.SetActive(go, false)
            end
        end
    end
end

function WorldBossNewBuffGetNode:FillBuffDescs(data)
    if not data then
        return
    end

    for i = 1, #data do
        local go = self.Content.transform:Find("BuffDesNode"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.BuffDesNode, self.Content)
            go.name = "BuffDesNode"..i
        end
        local tableName = string.format("%sIDGroup", AutoIds.IdSetting972)
        local id = CfUtils.GetStringIdGroupData(tableName, checkNumber(data[i].type).."_"..checkNumber(data[i].targetId))
        local vo = QuestConfMgr:GetInstance():GetWorldBossBuffVo(id)
        if vo then
            CfUtils.FillText(go, vo.desc)
        end
        KTool.SetActive(go, true)
    end

    if #data < self.Content.childCount then
        for i = #data + 1, self.Content.childCount do
            local go = self.Content.transform:Find("BuffDesNode"..i)
            if go then
                KTool.SetActive(go, false)
            end
        end
    end
end

function WorldBossNewBuffGetNode:OnBtnClose()
    UINavigationBarRoot.Instance:SetActive(true)
    if self._timeClick > 0 then
        return
    end
    CfUtils.SetTopCommonActive(true)
    CfUtils.RefreshTopGoods({Constants.Currency.WorldBossBuffCurrency})
    CS.UnityEngine.GameObject.Destroy(self.controller.gameObject)
end

--刷新
function WorldBossNewBuffGetNode:OnBtnRefresh()
    if self._timeClick > 0 then
        return
    end

    local consumId = QuestConfMgr:GetInstance():GetWorldBossBuffRefreshConsumeId()
    local num = QuestConfMgr:GetInstance():GetWorldBossBuffRefreshConsumeNum()
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(consumId)
    if not vo then
        return
    end
    local freeNum = worldBossComponent:GetBuyBuffFreeNum()
    local consumVo = {
        goodsId = vo.id,
        num = num
    }
    if freeNum <= 0 then
        if GoodsUtils.GetThingNo(consumVo.goodsId) < num then 
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.id)
            GameUtils.Toast(localize("_name_不足", {_name_ = vo.name}))
            return 
        end
    end

    worldBossComponent:WorldBossExtractBuffReq(function()
        if freeNum <= 0 then
            GoodsUtils.DrawRewards({
                {
                    num = -consumVo.num,
                    goodsId = consumVo.goodsId
                }
            }, true)
        end
        self:Refresh(worldBossComponent:GetCurBossBuffs())
    end)
end

function WorldBossNewBuffGetNode:OnDestroy()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return WorldBossNewBuffGetNode
